pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            success = result;
        } catch {
            return;
        }
        assertTrue(success);
    }
}

