pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint v) public {
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        // empty array: _tos length == 0
        address[] memory _tos = new address[](0);
        bool ok;
        try c.transfer(from, caddress, _tos, v) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

